                    ["12", "Cautious", "Cautious", "Threatening"],
                    ["13", "Cautious", "Cautious", "Threatening"],
                    ["14", "Cautious", "Cautious", "Threatening"],
                    ["15", "Cautious", "Threatening", "Threatening"],
                    ["16", "Threatening", "Threatening", "Hostile"],
                    ["17", "Threatening", "Threatening", "Hostile"],
                    ["18", "Threatening", "Threatening", "Hostile"],
                    ["19", "Hostile", "Hostile", "Hostile"],
